/**
 * Effect check for exo's switches. The text check in selfprotect.ts tries to
 * see a change coming; a command can always be spelled so it does not. This
 * one looks at the result instead: the state of the switches before a call
 * that can change things, compared with the state after it.
 *
 * A change made during a Claude call is put to the person: keep it or undo
 * it. Without an answer (Esc, no UI) it is undone. Switching exo ON (the
 * DISABLED file gone) is never undone.
 *
 * The person's own change in a second terminal can land inside a running
 * call; that is why the dialog asks instead of undoing straight away.
 */
import type { Host } from './adapter/host'
import { exoDir } from './killswitch'

export interface ControlState {
  disabled: boolean
  /** rules.json as text; null when absent. */
  rules: string | null
  /** Per settings file: the JSON of exo's entry, null without one. */
  settings: Record<string, string | null>
  /** `/exo off` and module overrides as stored. */
  prefs: string
}

export const settingsFiles = (home: string) => [`${home}/.claude/settings.json`, `${home}/.claude/settings.local.json`]

const UNREADABLE = '<unreadable>'

/** exo's entry in a settings file, as JSON text. */
export function exoEntry(text: string): string | null {
  let json: unknown
  try {
    json = JSON.parse(text)
  } catch {
    return UNREADABLE
  }
  const pc = (json as { pluginConfigs?: Record<string, unknown> })?.pluginConfigs
  if (!pc || typeof pc !== 'object') return null
  const entries = Object.entries(pc).filter(([k]) => k === 'exo' || k.startsWith('exo@'))
  return entries.length ? JSON.stringify(Object.fromEntries(entries)) : null
}

export async function readControl(host: Host, home: string): Promise<ControlState> {
  const dir = exoDir(home)
  const disabled = await host.exists(`${dir}/DISABLED`).catch(() => false)
  const rules = (await host.exists(`${dir}/rules.json`).catch(() => false)) ? await host.readFile(`${dir}/rules.json`).catch(() => UNREADABLE) : null
  const settings: Record<string, string | null> = {}
  for (const f of settingsFiles(home)) {
    settings[f] = (await host.exists(f).catch(() => false)) ? exoEntry(await host.readFile(f).catch(() => '')) : null
  }
  const prefs = JSON.stringify((await host.storeGet('prefs').catch(() => null)) ?? null)
  return { disabled, rules, settings, prefs }
}

export type ControlChange =
  | { kind: 'disabled' }
  | { kind: 'rules'; before: string | null }
  | { kind: 'settings'; file: string; before: string | null }
  | { kind: 'prefs'; before: string }

/** What changed for the worse; switching exo on is no change worth asking about. */
export function diffControl(a: ControlState, b: ControlState): ControlChange[] {
  const out: ControlChange[] = []
  if (!a.disabled && b.disabled) out.push({ kind: 'disabled' })
  if (a.rules !== b.rules) out.push({ kind: 'rules', before: a.rules })
  for (const f of Object.keys(b.settings)) if (a.settings[f] !== b.settings[f]) out.push({ kind: 'settings', file: f, before: a.settings[f] ?? null })
  if (a.prefs !== b.prefs) out.push({ kind: 'prefs', before: a.prefs })
  return out
}

const norm = (p: string) => p.replace(/\/+/g, '/').toLowerCase()

/** Whether a change is the one to the file at `path`. */
export function changeIs(c: ControlChange, path: string): boolean {
  const p = norm(path)
  if (c.kind === 'disabled') return p.endsWith('/.claude/exo/disabled')
  if (c.kind === 'rules') return p.endsWith('/.claude/exo/rules.json')
  if (c.kind === 'settings') return norm(c.file) === p
  return false
}

export function describe(c: ControlChange): string {
  switch (c.kind) {
    case 'disabled':
      return 'the kill switch ~/.claude/exo/DISABLED was created'
    case 'rules':
      return 'the house rules (rules.json) were changed'
    case 'settings':
      return `exo's settings in ${c.file.split('/').pop()} were changed`
    case 'prefs':
      return "exo's stored switches (/exo) were changed"
  }
}

/** Puts exo's entry of a settings file back to `before`; other keys stay. */
export function restoreEntry(text: string, before: string | null): string | null {
  let json: Record<string, unknown>
  try {
    json = JSON.parse(text) as Record<string, unknown>
  } catch {
    return null
  }
  if (before === UNREADABLE) return null
  const pc = { ...((json.pluginConfigs as Record<string, unknown> | undefined) ?? {}) }
  for (const k of Object.keys(pc)) if (k === 'exo' || k.startsWith('exo@')) delete pc[k]
  if (before) Object.assign(pc, JSON.parse(before) as Record<string, unknown>)
  const next: Record<string, unknown> = { ...json }
  if (Object.keys(pc).length) next.pluginConfigs = pc
  else delete next.pluginConfigs
  return JSON.stringify(next, null, 2) + '\n'
}

/** Undoes one change; returns false when it could not. */
export async function undo(host: Host, home: string, c: ControlChange): Promise<boolean> {
  const dir = exoDir(home)
  try {
    if (c.kind === 'disabled') {
      const r = await host.run(['rm', '-f', `${dir}/DISABLED`])
      return r.exitCode === 0
    }
    if (c.kind === 'rules') {
      if (c.before === null) {
        const r = await host.run(['rm', '-f', `${dir}/rules.json`])
        return r.exitCode === 0
      }
      if (c.before === UNREADABLE) return false
      await host.writeFile(`${dir}/rules.json`, c.before)
      return true
    }
    if (c.kind === 'settings') {
      const now = await host.readFile(c.file)
      const next = restoreEntry(now, c.before)
      if (next === null) return false
      await host.writeFile(c.file, next)
      return true
    }
    await host.storeSet('prefs', JSON.parse(c.before))
    return true
  } catch {
    return false
  }
}

export const KEEP = 'Keep'
export const REVERT = 'Undo'
export const QUESTION = (what: string) => `Something about exo changed during a Claude call: ${what}. Keep it?`

/**
 * After work that could have changed the switches: each change is put to the
 * person (keep / undo); undone without a yes. Returns what was undone.
 * `skip` leaves out the change the person already allowed up front.
 */
export async function settleEffects(
  host: Host,
  home: string,
  before: ControlState,
  interactive: boolean,
  untimed: <T>(p: Promise<T>) => Promise<T> = p => p,
  skip: (c: ControlChange) => boolean = () => false,
): Promise<string[]> {
  const changes = diffControl(before, await readControl(host, home))
  const undone: string[] = []
  for (const c of changes) {
    if (skip(c)) continue
    let keep = false
    if (interactive) {
      try {
        keep = (await untimed(host.ask(QUESTION(describe(c)), [KEEP, REVERT]))) === KEEP
      } catch {
        keep = false
      }
    }
    if (!keep && (await undo(host, home, c))) undone.push(describe(c))
  }
  return undone
}

export const undoneText = (undone: string[]) =>
  `exo: undone – ${undone.join('; ')}. Only you can switch exo off (touch ~/.claude/exo/DISABLED in a terminal of your own, or /exo off).`

files.core/selfprotect.ts:
/**
 * exo protects its own switches from the agent it guards.
 *
 * Without this, Claude could switch every guard off with one call
 * (`touch ~/.claude/exo/DISABLED`, emptying rules.json, setting an exo
 * option to false in settings.json). Changing those files therefore needs
 * a yes from the person in a dialog; without an interactive UI it is
 * denied. Reading them stays free.
 *
 * Deliberately broad, because the cheap tricks must not work:
 * - Bash is judged on the raw text AND on the words as the shell cooks them
 *   (`DIS""ABLED` is `DISABLED`), and the bare file names count on their
 *   own: the Bash tool keeps its working directory between calls, so a
 *   `cd ~/.claude/exo` in one call and `touch DISABLED` in the next must
 *   not slip through.
 * - "Only reads" is a short list of programs that cannot run other
 *   programs, with no writing redirect (`>&file` included) and no
 *   environment prefix.
 * - Paths are normalised (`//`, `.`, `..`) and compared without case
 *   (macOS file systems ignore it), and resolved through symlinks.
 * - Tools exo does not know are checked for any path into ~/.claude/exo.
 *
 * A seatbelt, not a sandbox: an agent with a shell can still find another
 * way (editing the mod itself, base64 piped into a shell). This closes the
 * obvious doors.
 */
import { MODULE_IDS } from './config/config'
import type { Script } from './shell/parse'
import type { ToolCall } from './dispatcher/dispatcher'
import { READ_TOOLS } from './tools'
import { parse } from './shell/parse'
import { SHELLS, commands } from './shell/words'
import type { Cmd } from './shell/words'
import { joinPath } from './cwd'
import type { CwdGuess } from './cwd'

/** Programs that only read and cannot run another program. */
const READ_ONLY = new Set(['cat', 'head', 'tail', 'ls', 'wc', 'stat', 'file', 'grep', 'egrep', 'fgrep', 'jq', 'diff', 'cmp', 'echo', 'printf', 'test', '[', 'pwd', 'cd', 'true', 'md5', 'md5sum', 'shasum', 'sha256sum'])
const FILE_TOOLS = new Set(['Write', 'Edit', 'NotebookEdit'])

const OPTION_KEYS = [...MODULE_IDS, 'prodHosts', 'secretAllowPaths', 'snapshotMaxMb', 'dietMaxKb', 'dietMaxLines', 'testCommand', 'quietHours']

/** `/a//b/./c/../d` → `/a/b/d`, lower case. */
export function normPath(p: string): string {
  const abs = p.startsWith('/')
  const out: string[] = []
  for (const part of p.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return ((abs ? '/' : '') + out.join('/')).toLowerCase()
}

const isExoPath = (p: string) => /(^|\/)\.claude\/exo(\/|$)/.test(normPath(p))
const isSettings = (p: string) => /(^|\/)\.claude\/settings(\.local)?\.json$/.test(normPath(p))
const mentionsExoConfig = (text: string) => /\bexo\b|pluginConfigs/i.test(text) || OPTION_KEYS.some(k => text.includes(`"${k}"`))

/** Text that names one of exo's switches, in any spelling the shell accepts. */
function namesControl(text: string): boolean {
  const t = text.replace(/\/+/g, '/')
  return (
    /\.claude\/exo\b/i.test(t) ||
    /\bexo\/(disabled|rules\.json)\b/i.test(t) ||
    /\bDISABLED\b/.test(t) ||
    (/\bdisabled\b/i.test(t) && /\.claude|\bexo\b/i.test(t)) ||
    /\brules\.json\b/i.test(t) ||
    /pluginConfigs/i.test(t) ||
    /\.claude\/dev-mods\b/i.test(t) ||
    (/settings(\.local)?\.json/i.test(t) && /\bexo\b/i.test(t)) ||
    (/\bclaude\b[\s\S]*\bplugins?\b[\s\S]*\b(disable|uninstall|remove|configure|update)\b/i.test(t) && /\bexo\b/i.test(t))
  )
}

/** Names a glob could expand to that matter here. */
const CONTROL_NAMES = ['.claude', 'exo', 'disabled', 'rules.json', 'settings.json', 'settings.local.json', 'dev-mods']

/** A glob word (`DIS*`, `e?o`, `[D]ISABLED`) whose segments could hit a control name. */
export function globHitsControl(word: string): boolean {
  return word.split('/').some(seg => {
    if (!/[*?[]/.test(seg)) return false
    // `*` or `??` alone carries no hint of a name; bash would not match a
    // dot name (`.claude`) with it either.
    if (/^[*?]+$/.test(seg)) return false
    let re = ''
    for (let i = 0; i < seg.length; i++) {
      const ch = seg[i]!
      if (ch === '*') re += '.*'
      else if (ch === '?') re += '.'
      else if (ch === '[') {
        const end = seg.indexOf(']', i + 2)
        if (end === -1) re += '\\['
        else {
          re += '[' + seg.slice(i + 1, end).replace(/^!/, '^').replace(/\\/g, '\\\\') + ']'
          i = end
        }
      } else re += ch.replace(/[.+^${}()|\\]/g, '\\$&')
    }
    try {
      const rx = new RegExp(`^${re}$`, 'i')
      return CONTROL_NAMES.some(n => (!n.startsWith('.') || seg.startsWith('.')) && rx.test(n))
    } catch {
      return true // a pattern we cannot read: assume the worst
    }
  })
}

/**
 * Programs whose real command is invisible: `eval`, a shell reading its
 * script from a pipe, decoding into a pipe (`base64 -d | sh`).
 */
function opaque(script: Script, cmds: Cmd[]): boolean {
  if (cmds.some(c => c.program === 'eval' || c.program === 'source' || c.program === '.')) return true
  const decodes = cmds.some(
    c => (c.program === 'base64' && c.argv.some(a => /^(-d|-D|--decode)$/.test(a))) || (c.program === 'xxd' && c.argv.includes('-r')) || (c.program === 'openssl' && c.argv.includes('-d')),
  )
  if (decodes) return true
  const pipedShell = (s: Script): boolean =>
    s.entries.some(e =>
      e.pipeline.commands.some((c, i) => {
        if (c.type !== 'simple') return pipedShell(c.body)
        const prog = (c.words[0]?.text ?? '').split('/').pop() ?? ''
        const args = c.words.slice(1).filter(w => !w.text.startsWith('-'))
        return i > 0 && SHELLS.has(prog) && args.length === 0
      }),
    )
  return pipedShell(script)
}

/** Every word the shell would see, cooked: argv, assignments, redirect targets, heredocs. */
function cookedText(cmds: Cmd[]): string {
  const parts: string[] = []
  for (const c of cmds) {
    parts.push(...c.argv, ...c.assigns)
    for (const r of c.redirects) {
      if (r.target) parts.push(r.target.text)
      if (r.heredoc) parts.push(r.heredoc.body)
    }
  }
  return parts.join(' ')
}

/** Whether a redirect writes to a file (`>&2` does not, `>&file` does). */
function writes(op: string, target: string | undefined): boolean {
  if (target === '/dev/null') return false
  if (op === '>&' || op === '<&') return op === '>&' && !/^(\d+|-)$/.test(target ?? '')
  return op === '>' || op === '>>' || op === '>|' || op === '&>' || op === '&>>' || op === '<>'
}

/** Only programs from READ_ONLY, no writing redirect, no environment prefix. */
function onlyReads(cmds: Cmd[]): boolean {
  return cmds.every(c => READ_ONLY.has(c.program) && c.assigns.length === 0 && !c.via.some(v => v.kind === 'env' || v.kind === 'xargs') && !c.redirects.some(r => writes(r.op, r.target?.text)))
}

/** Strings inside a tool's input, a few levels deep. */
function strings(v: unknown, depth = 0, out: string[] = []): string[] {
  if (depth > 4 || out.length > 200) return out
  if (typeof v === 'string') out.push(v)
  else if (Array.isArray(v)) for (const x of v) strings(x, depth + 1, out)
  else if (v && typeof v === 'object') for (const x of Object.values(v)) strings(x, depth + 1, out)
  return out
}

/** Paths a file-writing call targets, for the symlink check. */
export function targetPaths(call: ToolCall): string[] {
  const input = call.input
  if (FILE_TOOLS.has(call.tool)) return [String(input.file_path ?? input.notebook_path ?? '')].filter(Boolean)
  if (call.tool === 'Bash' || READ_TOOLS.has(call.tool)) return []
  return strings(input).filter(s => s.startsWith('/') && !s.includes('\n') && s.length < 4096)
}

/** Inside ~/.claude (exo's folder included): every write there counts. */
const inClaudeDir = (cwd: string) => /(^|\/)\.claude(\/|$)/.test(normPath(cwd))

/**
 * Whether a tool call would change exo's switches (without the file
 * system). `cwd` are the Bash tool's working directories before and after
 * the command's own `cd`s, when exo follows them.
 */
export function touchesControl(call: ToolCall, cwd?: { before: CwdGuess; after: CwdGuess }, home?: string): boolean {
  const input = call.input
  if (call.tool === 'Bash') {
    const raw = typeof input.command === 'string' ? input.command : ''
    const r = parse(raw)
    if (!r.ok) return namesControl(raw)
    const cmds = commands(r.script)
    if (opaque(r.script, cmds)) return true
    if (onlyReads(cmds)) return false
    if (namesControl(raw) || namesControl(cookedText(cmds))) return true
    if (cwd) {
      const dirs = [cwd.before, cwd.after].filter(g => g.known).map(g => g.cwd)
      // standing in ~/.claude or below: any write may hit a switch by a relative name
      if (dirs.some(inClaudeDir)) return true
      // relative targets resolved against the working directory
      const rel = cmds.flatMap(c => [...c.argv.slice(1), ...c.redirects.map(x => x.target?.text ?? '')]).filter(t => t && !t.startsWith('-') && !t.startsWith('/'))
      for (const d of dirs) for (const t of rel) {
        const abs = joinPath(d, t, home)
        if (isExoPath(abs) || isSettings(abs)) return true
      }
    }
    const words = cmds.flatMap(c => [...c.words, ...c.redirects.flatMap(x => (x.target ? [x.target] : []))])
    if (words.some(w => w.glob && globHitsControl(w.text))) return true
    // Pieces in variables (`a=.cla; touch ~/${a}ude/exo`): with an expansion
    // in play, a fragment of `.claude` or `DISABLED` is enough. Kept narrow on
    // purpose: `claude` or `exo` alone would hit every write in ~/claude.
    return words.some(w => w.expansion) && /\.cla|disab/i.test(raw)
  }
  if (FILE_TOOLS.has(call.tool)) {
    const path = String(input.file_path ?? input.notebook_path ?? '')
    if (isExoPath(path)) return true
    if (isSettings(path)) {
      const text = [input.content, input.old_string, input.new_string, input.new_source].filter(x => typeof x === 'string').join('\n')
      return mentionsExoConfig(text)
    }
    return false
  }
  if (READ_TOOLS.has(call.tool)) return false
  // A tool exo does not know (an MCP server's, a later built-in): any path
  // into ~/.claude/exo, or a settings file next to exo options, counts.
  const all = strings(input)
  return all.some(s => isExoPath(s)) || (all.some(s => isSettings(s)) && all.some(s => mentionsExoConfig(s)))
}

/**
 * The same, with the targets of file-writing calls resolved through
 * symlinks (`realPath` from the engine). A path that does not resolve yet
 * (a new file) is judged by its parent's real path.
 */
export async function touchesControlResolved(
  call: ToolCall,
  realPath: (path: string) => Promise<string>,
  cwd?: { before: CwdGuess; after: CwdGuess },
  home?: string,
): Promise<boolean> {
  if (touchesControl(call, cwd, home)) return true
  for (const p of targetPaths(call)) {
    let real: string | null = null
    for (let cur = p, tail = ''; ; ) {
      try {
        real = (await realPath(cur || '/')) .replace(/\/$/, '') + tail
        break
      } catch {
        if (!cur || cur === '/') break
        const cut = cur.lastIndexOf('/')
        tail = cur.slice(cut) + tail
        cur = cur.slice(0, cut)
      }
    }
    // Nothing resolved, not even the root: the file system cannot answer,
    // so the call is treated as touching (fail closed).
    if (real === null) return true
    if (real !== p && (isExoPath(real) || (isSettings(real) && touchesControl({ ...call, input: { ...call.input, file_path: real } })))) return true
  }
  return false
}

export const ALLOW = 'Allow'
export const REFUSE = 'Deny'

export const CONTROL_QUESTION = (what: string) => `Claude wants to change exo's control files (kill switch, house rules or exo settings): ${what} – allow?`

export const CONTROL_DENIED =
  "exo: change to exo's control files denied. Only you can switch exo off: touch ~/.claude/exo/DISABLED in a terminal of your own, or /exo off."

